const SCH=q=>"https://scholar.google.com/scholar?q="+encodeURIComponent(q);
const DOI=d=>"https://doi.org/"+d;
const TYPES={paper:{es:"Paper",en:"Paper"},libro:{es:"Libro",en:"Book"},informe:{es:"Informe",en:"Report"},curso:{es:"Curso",en:"Course"},ficha:{es:"Ficha técnica",en:"Product sheet"},encuesta:{es:"Encuesta",en:"Survey"}};
const BOOKC={paper:["#2F4A8A","#FFC726"],libro:["#1F6B4A","#F4EBD9"],informe:["#8A3B2F","#FFD9B8"],curso:["#5A3F8A","#F4EBD9"],ficha:["#B8662E","#FFF3D6"],encuesta:["#7A2F55","#FFD6E4"]};
const SHELVES=[["anden",{es:"Andenes",en:"Docks"}],["bodega",{es:"Bodega",en:"Warehouse"}],["ultima",{es:"Última milla",en:"Last mile"}],["rutas",{es:"Rutas",en:"Routes"}]];
const SOURCES=[
 {id:"bailey1952",shelf:"anden",sp:"Bailey · Colas y citas",spEn:"Bailey · Queues and appointments",au:"N. T. J. Bailey",yr:"1952",ti:{es:"Un estudio de colas y sistemas de citas en consultorios externos de hospitales, con especial referencia a los tiempos de espera",en:"A study of queues and appointment systems in hospital out-patient departments, with special reference to waiting-times",orig:"A study of queues and appointment systems in hospital out-patient departments, with special reference to waiting-times"},ve:"Journal of the Royal Statistical Society, Series B 14(2), 185–199",ty:"paper",labs:["bailey"],url:SCH("Bailey 1952 A study of queues and appointment systems in hospital out-patient departments"),search:true,
  idea:{es:"Bailey simuló a mano las esperas en las consultas de un hospital. Su receta: citar a dos pacientes al abrir y después a uno cada tanto, al ritmo de atención. Así el médico casi nunca queda sin nadie y los pacientes esperan mucho menos que si llegan todos juntos.",en:"Bailey simulated hospital clinic waits by hand. His recipe: book two patients at opening, then one at a time at the service pace. The doctor is almost never idle, and patients wait far less than if they all arrive together."}},
 {id:"welch1952",shelf:"anden",sp:"Welch & Bailey · The Lancet",spEn:"Welch & Bailey · The Lancet",au:"J. D. Welch & N. T. J. Bailey",yr:"1952",ti:{es:"Sistemas de citas en consultorios externos de hospitales",en:"Appointment systems in hospital outpatient departments",orig:"Appointment systems in hospital outpatient departments"},ve:"The Lancet 259(6718), 1105–1108",ty:"paper",labs:["bailey"],url:SCH("Welch Bailey 1952 Appointment systems in hospital outpatient departments Lancet"),search:true,
  idea:{es:"La versión para médicos del mismo estudio. Llevó la regla de Bailey de la estadística a la sala de espera, con ejemplos prácticos de cómo armar la agenda.",en:"The doctors' version of the same study. It took Bailey's rule from statistics to the waiting room, with practical examples of how to build the schedule."}},
 {id:"kaandorp2007",shelf:"anden",sp:"Kaandorp & Koole · Agenda óptima",spEn:"Kaandorp & Koole · Optimal schedule",au:"G. C. Kaandorp & G. Koole",yr:"2007",ti:{es:"Agenda óptima de citas ambulatorias",en:"Optimal outpatient appointment scheduling",orig:"Optimal outpatient appointment scheduling"},ve:"Health Care Management Science 10(3), 217–229",ty:"paper",labs:["bailey"],url:SCH("Kaandorp Koole 2007 Optimal outpatient appointment scheduling"),search:true,
  idea:{es:"Buscan la mejor agenda posible pesando tres costos a la vez: la espera de los clientes, el tiempo ocioso y el atraso del cierre. Muestran que la regla de Bailey es la mejor solo con ciertos pesos: cambia la importancia de cada costo y cambia la agenda ideal.",en:"They search for the best possible schedule weighing three costs at once: customer waiting, idle time and late closing. They show Bailey's rule is best only for certain weights: change how much each cost matters and the ideal schedule changes."}},
 {id:"lindley1952",shelf:"anden",sp:"Lindley · Una fila, un servidor",spEn:"Lindley · One line, one server",au:"D. V. Lindley",yr:"1952",ti:{es:"La teoría de colas con un solo servidor",en:"The theory of queues with a single server",orig:"The theory of queues with a single server"},ve:"Proceedings of the Cambridge Philosophical Society 48(2), 277–289",ty:"paper",labs:["bailey","fila"],url:SCH("Lindley 1952 The theory of queues with a single server"),search:true,
  idea:{es:"La ecuación más simple de las filas: tu espera es la espera del anterior, más lo que demoró, menos lo que tardaste en llegar después de él; nunca menos que cero. Las simulaciones de un andén del laboratorio la usan por debajo.",en:"The simplest queue equation: your wait is the previous customer's wait, plus their service, minus the time between your arrivals; never below zero. The lab's single-dock simulations run on it."}},
 {id:"erlang1917",shelf:"anden",sp:"Erlang · Centrales telefónicas",spEn:"Erlang · Telephone exchanges",au:"A. K. Erlang",yr:"1917",ti:{es:"Solución de algunos problemas de la teoría de probabilidades relevantes para las centrales telefónicas automáticas",en:"Solution of some problems in the theory of probabilities of significance in automatic telephone exchanges",orig:"Løsning af nogle Problemer fra Sandsynlighedsregningen af Betydning for de automatiske Telefoncentraler"},ve:{es:"Elektroteknikeren 13 · en inglés: «Solution of some problems in the theory of probabilities of significance in automatic telephone exchanges»",en:"Elektroteknikeren 13 · English: “Solution of some problems in the theory of probabilities of significance in automatic telephone exchanges”"},ty:"paper",labs:["fila"],url:SCH("Erlang 1917 Solution of some problems in the theory of probabilities of significance in automatic telephone exchanges"),search:true,
  idea:{es:"Un ingeniero danés quería saber cuántas líneas necesitaba una central para que casi nadie esperara. De ahí nacen las fórmulas de Erlang, que hoy sirven igual para andenes, cajas de supermercado y centros de llamadas.",en:"A Danish engineer wanted to know how many lines an exchange needed so almost nobody would wait. That gave birth to the Erlang formulas, used today for docks, supermarket checkouts and call centers alike."}},
 {id:"winston1977",shelf:"anden",sp:"Winston · La fila más corta",spEn:"Winston · The shortest line",au:"W. Winston",yr:"1977",ti:{es:"Optimalidad de la regla de la fila más corta",en:"Optimality of the shortest line discipline",orig:"Optimality of the shortest line discipline"},ve:"Journal of Applied Probability 14(1), 181–189",ty:"paper",labs:["fila"],url:SCH("Winston 1977 Optimality of the shortest line discipline"),search:true,
  idea:{es:"Demuestra que, si cada cliente debe elegir una fila al llegar y los servidores son iguales, mandarlo a la fila más corta es la mejor regla. Es la lógica del «jefe de patio».",en:"Shows that if each customer must pick a line on arrival and servers are identical, sending them to the shortest line is the best rule. It is the logic of the “yard boss”."}},
 {id:"weber1978",shelf:"anden",sp:"Weber · Servidores en paralelo",spEn:"Weber · Parallel servers",au:"R. R. Weber",yr:"1978",ti:{es:"Sobre la asignación óptima de clientes a servidores en paralelo",en:"On the optimal assignment of customers to parallel servers",orig:"On the optimal assignment of customers to parallel servers"},ve:"Journal of Applied Probability 15(2), 406–413",ty:"paper",labs:["fila"],url:SCH("Weber 1978 On the optimal assignment of customers to parallel servers"),search:true,
  idea:{es:"Extiende el resultado de Winston a más tipos de tiempos de atención. La conclusión se mantiene: si hay que elegir fila al llegar, la más corta gana.",en:"Extends Winston's result to more kinds of service times. The conclusion holds: if you must choose a line on arrival, the shortest one wins."}},
 {id:"odoni",shelf:"anden",sp:"Odoni · MIT 1.203J",spEn:"Odoni · MIT 1.203J",au:"A. R. Odoni",yr:"2006",ti:{es:"1.203J Logistical and Transportation Planning Methods · notas de teoría de colas",en:"1.203J Logistical and Transportation Planning Methods · queueing theory notes"},ve:"MIT OpenCourseWare",ty:"curso",labs:["fila"],url:"https://ocw.mit.edu/search/?q=1.203J",search:true,
  idea:{es:"Curso del MIT de métodos para planificar logística y transporte. De sus notas salen las fórmulas M/M/1 y M/M/c que usamos para la puerta fija y la fila única.",en:"MIT course on logistics and transportation planning methods. Its notes give the M/M/1 and M/M/c formulas we use for the fixed door and the single queue."}},
 {id:"atri2024",shelf:"anden",sp:"ATRI · Camiones retenidos",spEn:"ATRI · Detained trucks",au:"American Transportation Research Institute (ATRI)",yr:"2024",ti:{es:"Impactos financieros y de seguridad de la retención de conductores (driver detention)",en:"Financial and safety impacts of truck driver detention"},ve:{es:"Informe de investigación",en:"Research report"},ty:"informe",labs:["fila"],url:"https://truckingresearch.org/2024/09/new-research-documents-substantial-financial-and-safety-impacts-from-truck-driver-detention/",
  idea:{es:"Encuesta a conductores y empresas de EE. UU.: los camiones quedan retenidos esperando carga o descarga en el 39 % de sus paradas. La espera en el andén no es un detalle: es dinero y seguridad.",en:"Survey of US drivers and carriers: trucks are detained waiting to load or unload at 39 % of their stops. Dock waiting is not a detail: it is money and safety."}},
 {id:"lu2013",shelf:"anden",sp:"Lu et al. · Filas y compras",spEn:"Lu et al. · Queues and purchases",au:"Y. Lu, A. Musalem, M. Olivares & A. Schilkrut",yr:"2013",ti:{es:"Medir el efecto de las filas en las compras de los clientes",en:"Measuring the effect of queues on customer purchases",orig:"Measuring the effect of queues on customer purchases"},ve:"Management Science 59(8), 1743–1763",ty:"paper",labs:["fila"],url:SCH("Lu Musalem Olivares Schilkrut 2013 Measuring the effect of queues on customer purchases"),search:true,
  idea:{es:"Con datos de video en el mostrador de un supermercado, miden cuánto cambia la compra según la fila. Hallazgo clave: la gente mira cuántos hay delante, no qué tan rápido avanza. Por eso una fila única larga puede espantar aunque sea más rápida.",en:"Using video data at a supermarket counter, they measure how purchases change with the line. Key finding: people look at how many are ahead, not how fast it moves. A long single queue can scare people off even when it is faster."}},
 {id:"bernoulli1713",shelf:"ultima",sp:"Bernoulli · Ars Conjectandi",spEn:"Bernoulli · Ars Conjectandi",au:"J. Bernoulli",yr:"1713",ti:{es:"El arte de conjeturar",en:"Ars Conjectandi",orig:"Ars Conjectandi"},ve:{es:"Basilea: Thurneysen · publicado tras su muerte",en:"Basel: Thurneysen · published after his death"},ty:"libro",labs:["nivel","ikea"],url:SCH("Bernoulli 1713 Ars Conjectandi"),search:true,
  idea:{es:"El libro que funda la probabilidad moderna. Estudia ensayos de sí o no repetidos, como lanzar una moneda o una entrega que llega o falla, y de ahí sale la distribución binomial. También enuncia la ley de los grandes números.",en:"The book that founded modern probability. It studies repeated yes-or-no trials, like a coin toss or a delivery that arrives or fails, which gives the binomial distribution. It also states the law of large numbers."}},
 {id:"boysen2019",shelf:"bodega",sp:"Boysen et al. · Bodegas e-commerce",spEn:"Boysen et al. · E-commerce warehouses",au:"N. Boysen, R. de Koster & F. Weidinger",yr:"2019",ti:{es:"Bodegas en la era del comercio electrónico: una revisión",en:"Warehousing in the e-commerce era: A survey",orig:"Warehousing in the e-commerce era: A survey"},ve:"European Journal of Operational Research 277(2), 396–411",ty:"paper",labs:["amazon"],url:SCH("Boysen de Koster Weidinger 2019 Warehousing in the e-commerce era: A survey"),search:true,
  idea:{es:"Revisa cómo el comercio electrónico cambió las bodegas: pedidos pequeños, muchísimos y para ya. Entre las respuestas está el almacenamiento disperso: el mismo producto en muchos lugares para que siempre haya uno cerca.",en:"Reviews how e-commerce changed warehouses: small orders, huge numbers of them, needed now. One answer is scattered storage: the same product in many places so one is always nearby."}},
 {id:"dekoster2007",shelf:"bodega",sp:"de Koster et al. · Picking",spEn:"de Koster et al. · Picking",au:"R. de Koster, T. Le-Duc & K. J. Roodbergen",yr:"2007",ti:{es:"Diseño y control del picking en bodegas: revisión de la literatura",en:"Design and control of warehouse order picking: A literature review",orig:"Design and control of warehouse order picking: A literature review"},ve:"European Journal of Operational Research 182(2), 481–501",ty:"paper",labs:["amazon"],url:SCH("de Koster Le-Duc Roodbergen 2007 Design and control of warehouse order picking: A literature review"),search:true,
  idea:{es:"La revisión clásica sobre preparar pedidos. Explica por qué caminar es lo más caro del picking y cómo bajarlo con el diseño del pasillo, la ubicación por rotación (ABC), juntar pedidos y elegir rutas.",en:"The classic review of order picking. It explains why walking is the most expensive part of picking and how to cut it with aisle design, location by turnover (ABC), batching orders and routing."}},
 {id:"ikeapax",shelf:"bodega",sp:"IKEA · PAX/FORSAND",spEn:"IKEA · PAX/FORSAND",au:"IKEA",yr:{es:"Ficha",en:"Sheet"},ti:{es:"Ficha de producto: clóset PAX/FORSAND 150×60×201 cm",en:"Product sheet: PAX/FORSAND wardrobe 150×60×201 cm"},ve:{es:"«Total de paquetes: 12» · 1,81 m³ armado, 0,276 m³ en cajas",en:"“Total packages: 12” · 1.81 m³ assembled, 0.276 m³ boxed"},ty:"ficha",labs:["ikea"],url:"https://www.ikea.com/cl/es/search/?q=PAX%20FORSAND",search:true,
  idea:{es:"La ficha oficial dice que este clóset llega en 12 paquetes. Armado ocupa 1,81 m³; en cajas, 0,276 m³: el camión lleva más de seis veces menos aire.",en:"The official sheet says this wardrobe comes in 12 packages. Assembled it takes 1.81 m³; boxed, 0.276 m³: the truck carries more than six times less air."}},
 {id:"rausand2004",shelf:"bodega",sp:"Rausand & Høyland · Confiabilidad",spEn:"Rausand & Høyland · Reliability",au:"M. Rausand & A. Høyland",yr:"2004",ti:{es:"Teoría de confiabilidad de sistemas: modelos, métodos estadísticos y aplicaciones",en:"System Reliability Theory: Models, Statistical Methods, and Applications",orig:"System Reliability Theory: Models, Statistical Methods, and Applications"},ve:{es:"Wiley, 2.ª edición",en:"Wiley, 2nd edition"},ty:"libro",labs:["ikea"],url:SCH("Rausand Høyland System Reliability Theory Models Statistical Methods and Applications"),search:true,
  idea:{es:"El manual de confiabilidad de sistemas. Un pedido de 12 cajas es un «sistema en serie»: basta que falle una pieza para que falle todo, y por eso las probabilidades de que cada parte salga bien se multiplican.",en:"The handbook of system reliability. A 12-box order is a “series system”: one failed part fails the whole thing, which is why the probabilities of each part going right multiply."}},
 {id:"cr2020",shelf:"bodega",sp:"Consumer Reports · Compras de muebles en línea",spEn:"Consumer Reports · Buying furniture online",au:"Consumer Reports",yr:"2020",ti:{es:"Encuesta sobre compras de muebles en línea",en:"Survey on online furniture purchases"},ve:{es:"Más de 38.000 miembros encuestados",en:"38,000+ members surveyed"},ty:"encuesta",labs:["ikea"],url:"https://www.consumerreports.org/furniture-stores/best-places-to-buy-furniture-for-your-home-a5751689199/",
  idea:{es:"Uno de cada diez compradores de muebles en línea recibió algo dañado o incompleto. La cifra real calza con lo que predice multiplicar riesgos pequeños.",en:"One in ten online furniture buyers got something damaged or incomplete. The real-world number fits what multiplying small risks predicts."}},
 {id:"fleming1975",shelf:"bodega",sp:"Fleming · Causa común",spEn:"Fleming · Common cause",au:"K. N. Fleming",yr:"1975",ti:{es:"Un modelo de confiabilidad para fallas de modo común en sistemas de seguridad redundantes",en:"A reliability model for common mode failures in redundant safety systems",orig:"A reliability model for common mode failures in redundant safety systems"},ve:{es:"Informe técnico de General Atomic (San Diego, 1974–1975)",en:"General Atomic technical report (San Diego, 1974–75)"},ty:"informe",labs:["ikea"],url:SCH("Fleming 1975 A reliability model for common mode failures in redundant safety systems"),search:true,
  idea:{es:"Advierte que no todas las fallas son independientes: una parte puede golpear a todas las piezas a la vez, como un pallet que se cae entero. Es el modelo de «causa común» o factor beta.",en:"Warns that not all failures are independent: one part can hit every piece at once, like a whole pallet falling. It is the “common cause” or beta-factor model."}},
 {id:"nhtsa2010",shelf:"rutas",sp:"NHTSA · Choques en cruces",spEn:"NHTSA · Intersection crashes",au:"NHTSA",yr:"2010",ti:{es:"Factores de choque en accidentes relacionados con intersecciones: una perspectiva en el lugar",en:"Crash Factors in Intersection-Related Crashes: An On-Scene Perspective",orig:"Crash Factors in Intersection-Related Crashes: An On-Scene Perspective"},ve:"DOT HS 811 366",ty:"informe",labs:["ups"],url:"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/811366",
  idea:{es:"En la muestra de choques investigados en el lugar, el 22 % ocurrió doblando a la izquierda y el 1,2 % doblando a la derecha.",en:"In the sample of crashes investigated on the scene, 22% happened while turning left and 1.2% while turning right."}},
 {id:"holland2017",shelf:"rutas",sp:"Holland et al. · ORION de UPS",spEn:"Holland et al. · UPS ORION",au:"C. Holland et al.",yr:"2017",ti:{es:"UPS optimiza sus rutas de reparto",en:"UPS Optimizes Delivery Routes",orig:"UPS Optimizes Delivery Routes"},ve:"INFORMS Journal on Applied Analytics (Interfaces) 47(1), 8–23",ty:"paper",labs:["ups"],url:DOI("10.1287/inte.2016.0875"),
  idea:{es:"Cuenta cómo UPS construyó ORION, el sistema que arma las rutas de sus conductores. Proyecta unos 161 millones de km menos al año con el despliegue completo.",en:"Tells how UPS built ORION, the system that plans its drivers' routes. It projects about 161 million fewer km a year at full deployment."}},
 {id:"dantzig1959",shelf:"rutas",sp:"Dantzig & Ramser · Ruteo",spEn:"Dantzig & Ramser · Routing",au:"G. B. Dantzig & J. H. Ramser",yr:"1959",ti:{es:"El problema del despacho de camiones",en:"The Truck Dispatching Problem",orig:"The Truck Dispatching Problem"},ve:"Management Science 6(1), 80–91",ty:"paper",labs:["ups"],url:DOI("10.1287/mnsc.6.1.80"),
  idea:{es:"El paper que inventó el problema de ruteo de vehículos, con un ejemplo de camiones que reparten combustible a estaciones de servicio. Todo software de rutas moderno desciende de aquí.",en:"The paper that invented the vehicle routing problem, using trucks delivering fuel to service stations. Every modern routing software descends from it."}},
 {id:"guide2006",shelf:"ultima",sp:"Guide et al. · El tiempo de lo devuelto",spEn:"Guide et al. · Time value of returns",au:"V. D. R. Guide Jr., G. C. Souza, L. N. Van Wassenhove & J. D. Blackburn",yr:"2006",ti:{es:"El valor temporal de las devoluciones comerciales",en:"Time Value of Commercial Product Returns",orig:"Time Value of Commercial Product Returns"},ve:"Management Science 52(8), 1200–1214",ty:"paper",labs:["quedatelo"],url:"https://cdn.vanderbilt.edu/vu-web/owen/files/publications/Time_Value_of_Commercial_ReturnsManagementScience.pdf",
  idea:{es:"Miden cuánto valor pierde un producto devuelto solo por esperar. En impresoras de inyección de HP, 1 % por semana; en herramientas eléctricas de Bosch, 1 % por mes. De ahí sale la «d» de este laboratorio: mismo producto, otro reloj.",en:"They measure how much value a returned product loses just by waiting. HP inkjet printers: 1 % a week; Bosch power tools: 1 % a month. That is this lab's “d”: same product, different clock."}},
 {id:"blackburn2004",shelf:"ultima",sp:"Blackburn et al. · Cadenas inversas",spEn:"Blackburn et al. · Reverse chains",au:"J. D. Blackburn, V. D. R. Guide Jr., G. C. Souza & L. N. Van Wassenhove",yr:"2004",ti:{es:"Cadenas de suministro inversas para devoluciones comerciales",en:"Reverse Supply Chains for Commercial Returns",orig:"Reverse Supply Chains for Commercial Returns"},ve:"California Management Review 46(2), 6–22",ty:"paper",labs:["quedatelo"],url:"https://cmr.berkeley.edu/2004/02/46-2-reverse-supply-chains-for-commercial-returns/",
  idea:{es:"Advierte que lo devuelto puede perder hasta 10–20 % de su valor solo por demoras. Si el producto se deprecia rápido, conviene decidir pronto y cerca del cliente, no mandarlo todo a un centro lejano.",en:"Warns that returns can lose up to 10–20 % of their value through delays alone. If a product depreciates fast, decide early and close to the customer instead of shipping everything to a distant center."}},
 {id:"amazon2025",shelf:"ultima",sp:"Amazon · Reembolso sin devolución",spEn:"Amazon · Returnless resolutions",au:"Amazon · Seller Forums",yr:"2026",ti:{es:"Reduce los costos de devolución con reembolsos sin devolución",en:"Reduce return costs with returnless resolutions",orig:"Reduce return costs with returnless resolutions"},ve:{es:"Ejemplo: «paying $8–$12 to ship back a $5 item»",en:"Example: “paying $8–$12 to ship back a $5 item”"},ty:"ficha",labs:["quedatelo"],url:"https://sellercentral.amazon.com/seller-forums/discussions/t/8f6ea88b-8672-426e-accb-7c9d7f6d911a",
  idea:{es:"De aquí sale el ejemplo: pagar 8 a 12 dólares por traer de vuelta un producto de 5. El reel usa el piso, 8, solo como flete. En otro aviso del foro, Amazon indica que el vendedor fija un precio máximo entre US$ 1 y US$ 75, y que la opción es solo para clientes sin historial de abuso.",en:"The example comes from here: paying $8–$12 to ship back a $5 item. The reel uses the low end, 8, as freight only. In another forum notice, Amazon says the seller sets a maximum price between $1 and $75, and the option is only for customers with no history of returns abuse."}},
 {id:"maister1976",shelf:"bodega",sp:"Maister · Ley de la raíz cuadrada",spEn:"Maister · Square root law",au:"D. H. Maister",yr:"1976",ti:{es:"La centralización de inventarios y la «ley de la raíz cuadrada»",en:"Centralisation of Inventories and the “Square Root Law”",orig:"Centralisation of Inventories and the “Square Root Law”"},ve:"International Journal of Physical Distribution 6(3), 124–134",ty:"paper",labs:["bodegas"],url:"https://doi.org/10.1108/eb014366",
  idea:{es:"Maister demuestra que el inventario total de un sistema crece con la raíz cuadrada del número de bodegas donde se guarda el producto. Si cuatro bodegas iguales se juntan en una, el stock de seguridad baja a la mitad, porque raíz de cuatro es dos. El supuesto: ciudades parecidas y ventas que suben y bajan cada una por su lado.",en:"Maister shows that total inventory in a system grows with the square root of the number of locations where the product is stocked. If four equal warehouses are pooled into one, safety stock halves, because the root of four is two. The assumption: similar cities whose sales rise and fall independently."}},
 {id:"eppen1979",shelf:"bodega",sp:"Eppen · Centralizar y la correlación",spEn:"Eppen · Pooling and correlation",au:"G. D. Eppen",yr:"1979",ti:{es:"Efectos de centralizar sobre los costos esperados en un problema del vendedor de diarios con varias ubicaciones",en:"Effects of Centralization on Expected Costs in a Multi-Location Newsboy Problem",orig:"Effects of Centralization on Expected Costs in a Multi-Location Newsboy Problem"},ve:"Management Science 25(5), 498–501",ty:"paper",labs:["bodegas"],url:"https://doi.org/10.1287/mnsc.25.5.498",
  idea:{es:"Eppen muestra que el ahorro de centralizar depende de cuánto se parecen las ventas de las ubicaciones. Si son independientes, el costo de seguridad crece con la raíz del número de ubicaciones; si están perfectamente correlacionadas, centralizar no ahorra nada. Es la objeción de Navidad hecha fórmula.",en:"Eppen shows that the saving from centralizing depends on how alike the locations' sales are. If they are independent, safety cost grows with the root of the number of locations; if perfectly correlated, centralizing saves nothing. It's the Christmas objection as a formula."}},
 {id:"johnson1997",shelf:"ultima",sp:"Johnson y McGeoch · El vendedor viajero",spEn:"Johnson & McGeoch · The traveling salesman",au:"D. S. Johnson & L. A. McGeoch",yr:"1997",ti:{es:"El problema del vendedor viajero: un caso de estudio de optimización local",en:"The Traveling Salesman Problem: A Case Study in Local Optimization",orig:"The Traveling Salesman Problem: A Case Study in Local Optimization"},ve:{es:"En Aarts y Lenstra (eds.), Local Search in Combinatorial Optimization, Wiley, pp. 215–310 · tabla 1",en:"In Aarts & Lenstra (eds.), Local Search in Combinatorial Optimization, Wiley, pp. 215–310 · table 1"},ty:"libro",labs:["vecino"],url:SCH("Johnson McGeoch The Traveling Salesman Problem: A Case Study in Local Optimization"),
  idea:{es:"Midieron las reglas rápidas para armar rutas en miles de ciudades al azar. La del vecino más cercano queda cerca de un cuarto sobre la cota de Held-Karp (25,6 % con 100 puntos, 26,0 % con 1.000 y 24,3 % con 10.000). Descruzar tramos (2-opt) baja el exceso a unos 5 %.",en:"They measured the quick route-building rules on thousands of random cities. Nearest neighbor ends up about a quarter above the Held-Karp bound (25.6 % with 100 points, 26.0 % with 1,000 and 24.3 % with 10,000). Uncrossing segments (2-opt) cuts the excess to about 5 %."}},
 {id:"richards2014",shelf:"bodega",sp:"Richards · Gestión de bodegas",spEn:"Richards · Warehouse Management",au:"G. Richards",yr:"2014",ti:{es:"Gestión de bodegas: guía completa para mejorar la eficiencia y bajar costos en la bodega moderna",en:"Warehouse Management: A Complete Guide to Improving Efficiency and Minimizing Costs in the Modern Warehouse",orig:"Warehouse Management: A Complete Guide to Improving Efficiency and Minimizing Costs in the Modern Warehouse"},ve:{es:"Kogan Page, 2.ª edición · cap. 13",en:"Kogan Page, 2nd edition · ch. 13"},ty:"libro",labs:["cadena"],url:SCH("Gwynne Richards Warehouse Management Kogan Page"),search:true,
  idea:{es:"Un pedido es perfecto solo si cumple todo a la vez: a tiempo, completo, sin daño y con la documentación correcta. Richards lo calcula multiplicando el porcentaje de cada requisito, y por eso cuatro áreas que cumplen bien pueden entregar un pedido perfecto bastante peor.",en:"An order is perfect only if it meets everything at once: on time, complete, damage free and with correct paperwork. Richards computes it by multiplying each requirement's percentage, which is why four areas that perform well can deliver a much worse perfect order."}},
 {id:"apqc2024",shelf:"bodega",sp:"APQC · Pedido perfecto",spEn:"APQC · Perfect order",au:"APQC",yr:{es:"Ficha",en:"Sheet"},ti:{es:"Desempeño del pedido perfecto (medida 101741)",en:"Perfect order performance (measure 101741)",orig:"Perfect order performance"},ve:{es:"«(% on time delivery) multiplied by (% complete orders) multiplied by (% damage free) multiplied by (% accurate documentation)»",en:"“(% on time delivery) multiplied by (% complete orders) multiplied by (% damage free) multiplied by (% accurate documentation)”"},ty:"ficha",labs:["cadena"],url:"https://www.apqc.org/resources/benchmarking/open-standards-benchmarking/measures/perfect-order-performance",
  idea:{es:"APQC, el centro estadounidense que compara procesos entre miles de empresas, define el indicador con la misma multiplicación de los cuatro requisitos. Su propio ejemplo: 0,98 × 0,97 × 0,99 × 0,82 ≈ 77 %.",en:"APQC, the US center that benchmarks processes across thousands of companies, defines the measure with the same multiplication of the four requirements. Its own example: 0.98 × 0.97 × 0.99 × 0.82 ≈ 77%."}}
];
const SRC={};SOURCES.forEach(s=>SRC[s.id]=s);

/* ---- formula helpers (symbols take the color of their lever) ---- */
let SYMC={};
const Vs=(sym,k)=>`<var class="v" data-k="${k}" style="--c:${SYMC[k]||"#FFC726"}">${sym}</var>`;
const FR=(a,b)=>`<span class="fr"><span class="nu">${a}</span><span class="de">${b}</span></span>`;
const HL=x=>`<mark>${x}</mark>`;
const OP=x=>`<span class="op">${x}</span>`;
const FL=x=>`<span class="br">⌊</span>${x}<span class="br">⌋</span>`;
const CE=x=>`<span class="br">⌈</span>${x}<span class="br">⌉</span>`;
const PA=x=>`<span class="br">(</span>${x}<span class="br">)</span>`;
const nArgs=st=>({p:st.p/1000,n:st.n,meta:st.meta,round:st.round,days:st.days,pen:Math.max(0,+st.pen||0),period:st.period,x:st.x/100});
const SV=(w,h,body)=>`<svg viewBox="0 0 ${w} ${h}" class="ill" role="img">${body}</svg>`;
